INSERT INTO `bank_soal` (`id`, `kategori`, `dimensi_id`, `skill`, `pertanyaan`, `tipe_soal`, `tingkat_kesulitan`, `petunjuk`, `pilihan_jawaban`, `jawaban`, `urutan`, `status`, `created_at`, `updated_at`) VALUES
('1', 'Situational Judgment Test (SJT)', '1', 'communication', 'Dalam diskusi kelompok, kamu memiliki pendapat yang berbeda dengan mayoritas anggota. Apa yang paling mungkin kamu lakukan?', 'dropdown', 'sulit', NULL, '[{\"id\": 1001, \"teks\": \"Menyampaikan pendapat dengan jelas dan membuka ruang diskusi.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 1002, \"teks\": \"Menunggu sampai ada anggota lain yang menyampaikan pendapat serupa.\", \"bobot\": 3, \"urutan\": 2, \"indikator\": \"netral\"}, {\"id\": 1003, \"teks\": \"Mengikuti keputusan kelompok agar diskusi cepat selesai.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 1004, \"teks\": \"Tidak menyampaikan pendapat karena takut menimbulkan perdebatan.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[1001]', '1', 'aktif', '2026-10-08 18:11:14', '2026-10-08 21:29:49'),
('2', 'Situational Judgment Test (SJT)', '1', 'interpersonal', 'Kamu masuk ke lingkungan organisasi baru dan belum mengenal siapa pun. Apa yang biasanya kamu lakukan?', 'multiple_choice', 'sulit', NULL, '[{\"id\": 2001, \"teks\": \"Mencoba menyapa dan membuka percakapan dengan anggota lain.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 2002, \"teks\": \"Menunggu ada orang yang mengajak berbicara terlebih dahulu.\", \"bobot\": 3, \"urutan\": 2, \"indikator\": \"netral\"}, {\"id\": 2003, \"teks\": \"Mengamati situasi cukup lama sebelum berinteraksi.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 2004, \"teks\": \"Memilih tetap sendiri selama memungkinkan.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[2001]', '2', 'aktif', '2026-10-08 18:11:14', '2026-10-08 21:29:49'),
('3', 'Emotional Intelligence', '3', 'emotional', 'Ketika seseorang memberikan kritik terhadap pekerjaanmu, respons yang paling menggambarkan dirimu adalah...', 'dropdown', 'sulit', NULL, '[{\"id\": 3001, \"teks\": \"Saya langsung memahami bahwa kritik tersebut merupakan masukan yang perlu dipertimbangkan.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 3002, \"teks\": \"Saya merasa kurang nyaman tetapi tetap mencoba mendengarkannya.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 3003, \"teks\": \"Saya cenderung memikirkan alasan orang tersebut mengkritik saya.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 3004, \"teks\": \"Saya merasa tersinggung dan sulit menerima kritik.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[3001]', '3', 'aktif', '2026-10-08 18:11:14', '2026-10-08 21:29:49'),
('4', 'Situational Judgment Test (SJT)', '4', 'interpersonal', 'Kelompokmu memiliki tugas dengan batas waktu tiga hari. Apa yang paling mungkin kamu lakukan?', 'dropdown', 'sedang', NULL, '[{\"id\": 4001, \"teks\": \"Membuat pembagian tugas dan jadwal penyelesaian sejak awal.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 4002, \"teks\": \"Menentukan tugas utama terlebih dahulu lalu menyesuaikan sisanya.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 4003, \"teks\": \"Mengerjakan bagian sendiri dan melihat perkembangan kelompok.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 4004, \"teks\": \"Menunggu sampai mendekati batas waktu sebelum menentukan langkah.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[4001]', '4', 'aktif', '2026-10-08 18:11:14', '2026-10-08 21:27:08'),
('5', 'Emotional Intelligence', '2', 'communication', 'Ketika menerima tugas baru dari dosen, mana yang paling menggambarkan cara kerjamu?', 'dropdown', 'sedang', 'Pilih satu pernyataan.', '[{\"id\": 5001, \"teks\": \"Saya mencatat detail tugas dan membuat daftar langkah pengerjaan.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 5002, \"teks\": \"Saya langsung mengerjakan bagian yang paling saya kuasai terlebih dahulu.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 5003, \"teks\": \"Saya menunggu penjelasan tambahan sebelum memulai.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 5004, \"teks\": \"Saya menyelesaikannya di saat terakhir agar tekanannya tidak terasa.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[5001]', '5', 'aktif', '2026-10-08 18:11:14', '2026-10-08 21:27:08'),
('6', 'Communication & Interpersonal Skills', '1', 'emotional', 'Seberapa nyaman kamu menyampaikan pendapat di depan kelompok yang besar?', 'scale', 'sedang', '1 = Sangat tidak nyaman, 5 = Sangat nyaman', '[{\"id\": 6001, \"teks\": \"1\", \"bobot\": 1, \"urutan\": 1, \"indikator\": \"sangat_tidak_nyaman\"}, {\"id\": 6002, \"teks\": \"2\", \"bobot\": 2, \"urutan\": 2, \"indikator\": \"tidak_nyaman\"}, {\"id\": 6003, \"teks\": \"3\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 6004, \"teks\": \"4\", \"bobot\": 4, \"urutan\": 4, \"indikator\": \"cukup_nyaman\"}, {\"id\": 6005, \"teks\": \"5\", \"bobot\": 5, \"urutan\": 5, \"indikator\": \"sangat_nyaman\"}]', NULL, '6', 'aktif', '2026-10-08 18:11:14', '2026-10-08 21:27:08'),
('7', 'Situational Judgment Test (SJT)', '3', 'interpersonal', 'Rekan kelompokmu terlambat mengerjakan bagian tugasnya dan mendekati batas pengumpulan. Apa tindakanmu?', 'multiple_choice', 'sulit', 'Pilih kartu tindakan yang paling sesuai.', '[{\"id\": 7001, \"teks\": \"Menghubungi rekan tersebut dan menawarkan bantuan mengerjakan bagianya.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 7002, \"teks\": \"Mengingatkan kembali tenggat waktu kepada rekan tersebut.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 7003, \"teks\": \"Melaporkan ke ketua kelompok agar bagian tersebut dialihkan.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 7004, \"teks\": \"Mengabaikan dan mengerjakan bagian saya sendiri.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[7001]', '7', 'aktif', '2026-10-08 18:11:14', '2026-10-08 21:29:49'),
('8', 'Communication & Interpersonal Skills', '4', 'communication', 'Urutkan prioritas berikut dari yang paling penting (1) hingga paling akhir (4) ketika menyelesaikan proyek kelompok.', 'multiple_choice', 'sulit', 'Klik untuk mengatur urutan.', '[{\"id\": 8001, \"teks\": \"Kualitas hasil akhir\", \"bobot\": 4, \"urutan\": 1, \"indikator\": \"prioritas_1\"}, {\"id\": 8002, \"teks\": \"Ketepatan waktu pengumpulan\", \"bobot\": 3, \"urutan\": 2, \"indikator\": \"prioritas_2\"}, {\"id\": 8003, \"teks\": \"Pembagian tugas yang adil\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"prioritas_3\"}, {\"id\": 8004, \"teks\": \"Suasana kerja yang menyenangkan\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"prioritas_4\"}]', '[8001]', '8', 'nonaktif', '2026-10-08 18:11:14', '2026-10-08 21:29:49'),
('9', 'Situational Judgment Test (SJT)', '2', 'emotional', 'Ketika kamu menghadapi situasi yang sangat menekan menjelang batas waktu pengumpulan, kamu cenderung...', 'dropdown', 'sulit', NULL, '[{\"id\": 9001, \"teks\": \"Tetap tenang, membuat daftar tugas, dan mengerjakan satu per satu.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 9002, \"teks\": \"Menyusun ulang prioritas agar tugas terpenting selesai lebih dulu.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 9003, \"teks\": \"Bekerja cepat tanpa rencana agar semua selesai bersamaan.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 9004, \"teks\": \"Merasa cemas dan kesulitan menentukan harus mulai dari mana.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[9001]', '9', 'aktif', '2026-10-08 18:11:14', '2026-10-08 21:29:49'),
('10', 'Communication & Interpersonal Skills', '3', 'communication', 'Dalam percakapan, hal mana yang paling sering kamu lakukan?', 'dropdown', 'mudah', NULL, '[{\"id\": 10001, \"teks\": \"Saya banyak bertanya untuk memastikan saya memahami pembicaraan.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 10002, \"teks\": \"Saya mendengarkan penuh sebelum memberikan tanggapan.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 10003, \"teks\": \"Saya sesekali memberikan tanggapan ketika ada kesempatan.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 10004, \"teks\": \"Saya lebih banyak diam dan menunggu percakapan selesai.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"netral\"}]', '[10001]', '10', 'aktif', '2026-10-08 18:11:14', '2026-10-08 21:28:25'),
('11', 'Emotional Intelligence', '1', 'interpersonal', 'Ketika ada anggota tim yang pendiam, apa yang biasanya kamu lakukan?', 'multiple_choice', 'sedang', 'Pilih satu kartu.', '[{\"id\": 11001, \"teks\": \"Saya mengajaknya berbicara pelan dan memberi ruang untuk bicara.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 11002, \"teks\": \"Saya melibatkannya pada bagian tugas yang sesuai kemampuannya.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 11003, \"teks\": \"Saya membiarkannya dan hanya mendekati jika ia mau.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 11004, \"teks\": \"Saya menganggap ia tidak tertarik bekerja sama.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[11001]', '11', 'aktif', '2026-10-08 18:11:14', '2026-10-08 21:29:49'),
('12', 'Communication & Interpersonal Skills', '4', 'emotional', 'Seberapa mudah kamu menyesuaikan diri ketika rencana berubah secara mendadak?', 'scale', 'sedang', '1 = Sangat sulit, 5 = Sangat mudah', '[{\"id\": 12001, \"teks\": \"1\", \"bobot\": 1, \"urutan\": 1, \"indikator\": \"sangat_sulit\"}, {\"id\": 12002, \"teks\": \"2\", \"bobot\": 2, \"urutan\": 2, \"indikator\": \"sulit\"}, {\"id\": 12003, \"teks\": \"3\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 12004, \"teks\": \"4\", \"bobot\": 4, \"urutan\": 4, \"indikator\": \"mudah\"}, {\"id\": 12005, \"teks\": \"5\", \"bobot\": 5, \"urutan\": 5, \"indikator\": \"sangat_mudah\"}]', NULL, '12', 'aktif', '2026-10-08 18:11:14', '2026-10-08 21:27:08'),
('13', 'Situational Judgment Test (SJT)', '1', 'communication', 'Dalam diskusi kelompok, kamu memiliki pendapat yang berbeda dengan mayoritas anggota. Apa yang paling mungkin kamu lakukan?', 'dropdown', 'sulit', NULL, '[{\"id\": 13001, \"teks\": \"Menyampaikan pendapat dengan jelas dan membuka ruang diskusi.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 13002, \"teks\": \"Menunggu sampai ada anggota lain yang menyampaikan pendapat serupa.\", \"bobot\": 3, \"urutan\": 2, \"indikator\": \"netral\"}, {\"id\": 13003, \"teks\": \"Mengikuti keputusan kelompok agar diskusi cepat selesai.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"negatif\"}, {\"id\": 13004, \"teks\": \"Tidak menyampaikan pendapat karena takut menimbulkan perdebatan.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[13001]', '1', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:29:49'),
('14', 'Situational Judgment Test (SJT)', '1', 'interpersonal', 'Kamu masuk ke lingkungan organisasi baru dan belum mengenal siapa pun. Apa yang biasanya kamu lakukan?', 'multiple_choice', 'sulit', NULL, '[{\"id\": 14001, \"teks\": \"Mencoba menyapa dan membuka percakapan dengan anggota lain.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 14002, \"teks\": \"Menunggu ada orang yang mengajak berbicara terlebih dahulu.\", \"bobot\": 3, \"urutan\": 2, \"indikator\": \"netral\"}, {\"id\": 14003, \"teks\": \"Mengamati situasi cukup lama sebelum berinteraksi.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"negatif\"}, {\"id\": 14004, \"teks\": \"Memilih tetap sendiri selama memungkinkan.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[14001]', '2', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:29:49'),
('15', 'Emotional Intelligence', '3', 'emotional', 'Ketika seseorang memberikan kritik terhadap pekerjaanmu, respons yang paling menggambarkan dirimu adalah...', 'dropdown', 'sulit', NULL, '[{\"id\": 15001, \"teks\": \"Saya langsung memahami bahwa kritik tersebut merupakan masukan yang perlu dipertimbangkan.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 15002, \"teks\": \"Saya merasa kurang nyaman tetapi tetap mencoba mendengarkannya.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 15003, \"teks\": \"Saya cenderung memikirkan alasan orang tersebut mengkritik saya.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 15004, \"teks\": \"Saya merasa tersinggung dan sulit menerima kritik.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[15001]', '3', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:29:49'),
('16', 'Situational Judgment Test (SJT)', '4', 'interpersonal', 'Kelompokmu memiliki tugas dengan batas waktu tiga hari. Apa yang paling mungkin kamu lakukan?', 'dropdown', 'sedang', NULL, '[{\"id\": 16001, \"teks\": \"Membuat pembagian tugas dan jadwal penyelesaian sejak awal.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 16002, \"teks\": \"Menentukan tugas utama terlebih dahulu lalu menyesuaikan sisanya.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 16003, \"teks\": \"Mengerjakan bagian sendiri dan melihat perkembangan kelompok.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 16004, \"teks\": \"Menunggu sampai mendekati batas waktu sebelum menentukan langkah.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[16001]', '4', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:27:08'),
('17', 'Communication & Interpersonal Skills', '2', 'communication', 'Ketika menerima instruksi yang belum sepenuhnya jelas, kamu biasanya...', 'multiple_choice', 'sedang', NULL, '[{\"id\": 17001, \"teks\": \"Meminta contoh konkret agar saya memahami maksud instruksi.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 17002, \"teks\": \"Mencoba memahami konteks dan tujuan dari instruksi tersebut.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 17003, \"teks\": \"Mengerjakan berdasarkan pemahaman saya terlebih dahulu.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 17004, \"teks\": \"Menunggu orang lain menjelaskan lebih lanjut.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[17001]', '5', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:27:08'),
('18', 'Situational Judgment Test (SJT)', '3', 'interpersonal', 'Dua anggota kelompokmu sedang berselisih karena perbedaan pendapat. Apa yang akan kamu lakukan?', 'multiple_choice', 'sedang', NULL, '[{\"id\": 18001, \"teks\": \"Mendengarkan kedua pihak dan membantu mencari solusi yang dapat diterima bersama.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 18002, \"teks\": \"Mencari fakta masalah sebelum menentukan langkah.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 18003, \"teks\": \"Membiarkan mereka menyelesaikan masalah sendiri.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 18004, \"teks\": \"Mendukung pihak yang menurut saya lebih dekat dengan saya.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[18001]', '6', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:27:08'),
('19', 'Emotional Intelligence', '1', 'emotional', 'Ketika suasana hati sedang buruk, saya biasanya...', 'dropdown', 'mudah', NULL, '[{\"id\": 19001, \"teks\": \"Menyadari penyebabnya dan mengatur diri sebelum berinteraksi dengan orang lain.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 19002, \"teks\": \"Mencoba melakukan kegiatan yang membuat suasana hati membaik.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 19003, \"teks\": \"Tetap beraktivitas meskipun emosi sedang kurang baik.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 19004, \"teks\": \"Mudah menunjukkan suasana hati kepada orang di sekitar.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[19001]', '7', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:28:25'),
('20', 'Situational Judgment Test (SJT)', '2', 'communication', 'Saat mengerjakan tugas, kamu menemukan dua cara berbeda untuk menyelesaikannya. Kamu cenderung...', 'multiple_choice', 'sedang', NULL, '[{\"id\": 20001, \"teks\": \"Membandingkan kedua cara berdasarkan fakta dan kemungkinan hasilnya.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 20002, \"teks\": \"Memilih cara yang pernah berhasil digunakan sebelumnya.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 20003, \"teks\": \"Mencoba salah satu cara dan melihat hasilnya.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 20004, \"teks\": \"Memilih cara yang terasa paling menarik.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[20001]', '8', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:27:08'),
('21', 'Communication & Interpersonal Skills', '1', 'interpersonal', 'Saat berada dalam kelompok yang anggotanya memiliki karakter berbeda-beda, saya...', 'multiple_choice', 'sedang', NULL, '[{\"id\": 21001, \"teks\": \"Berusaha memahami karakter setiap anggota dan menyesuaikan cara berkomunikasi.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 21002, \"teks\": \"Mencoba bersikap ramah kepada semua anggota.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 21003, \"teks\": \"Lebih nyaman berinteraksi dengan orang yang memiliki karakter mirip.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 21004, \"teks\": \"Tidak terlalu memikirkan perbedaan karakter.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[21001]', '9', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:27:08'),
('22', 'Situational Judgment Test (SJT)', '4', 'communication', 'Temanmu meminta bantuan menyelesaikan tugas ketika kamu juga memiliki pekerjaan yang harus diselesaikan.', 'dropdown', 'sulit', NULL, '[{\"id\": 22001, \"teks\": \"Menjelaskan kondisi saya dan menentukan waktu yang realistis untuk membantu.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 22002, \"teks\": \"Mencoba membantu sebisa mungkin setelah menyelesaikan bagian utama pekerjaan.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 22003, \"teks\": \"Langsung membantu meskipun pekerjaan saya mungkin terlambat.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 22004, \"teks\": \"Menolak tanpa menjelaskan alasannya.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[22001]', '10', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:29:49'),
('23', 'Emotional Intelligence', '3', 'emotional', 'Ketika harus mengambil keputusan penting, saya lebih sering...', 'dropdown', 'sedang', NULL, '[{\"id\": 23001, \"teks\": \"Mempertimbangkan dampak keputusan terhadap orang lain sekaligus kondisi yang ada.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 23002, \"teks\": \"Menggabungkan pertimbangan logis dan perasaan.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 23003, \"teks\": \"Lebih mengutamakan data dan hasil.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 23004, \"teks\": \"Mengikuti keputusan yang menurut saya paling masuk akal tanpa banyak mempertimbangkan perasaan orang lain.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[23001]', '11', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:29:49'),
('24', 'Situational Judgment Test (SJT)', '1', 'interpersonal', 'Dalam kegiatan organisasi, kamu diminta menjadi orang yang mempresentasikan hasil kerja kelompok.', 'multiple_choice', 'sedang', NULL, '[{\"id\": 24001, \"teks\": \"Saya bersedia mengambil peran tersebut dan mempersiapkan penyampaian materi.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 24002, \"teks\": \"Saya bersedia jika tidak ada anggota lain yang ingin melakukannya.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 24003, \"teks\": \"Saya lebih memilih membantu dari belakang layar.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"negatif\"}, {\"id\": 24004, \"teks\": \"Saya akan menghindari peran tersebut.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[24001]', '12', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:27:08'),
('25', 'Communication & Interpersonal Skills', '2', 'communication', 'Ketika mempelajari sesuatu yang baru, saya lebih mudah memahami jika...', 'multiple_choice', 'sedang', NULL, '[{\"id\": 25001, \"teks\": \"Ada contoh nyata yang menunjukkan penerapannya.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 25002, \"teks\": \"Ada penjelasan konsep sekaligus contoh.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 25003, \"teks\": \"Saya dapat mencoba sendiri.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 25004, \"teks\": \"Saya cukup membaca gambaran umumnya.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[25001]', '13', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:27:08'),
('26', 'Situational Judgment Test (SJT)', '4', 'emotional', 'Jika jadwal kegiatanmu berubah secara tiba-tiba, kamu biasanya...', 'multiple_choice', 'sedang', NULL, '[{\"id\": 26001, \"teks\": \"Menyesuaikan rencana dengan cepat dan menentukan prioritas baru.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 26002, \"teks\": \"Mencari alternatif yang paling memungkinkan.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 26003, \"teks\": \"Membutuhkan waktu untuk menyesuaikan diri.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 26004, \"teks\": \"Merasa terganggu karena rencana berubah.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[26001]', '14', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:29:49'),
('27', 'Communication & Interpersonal Skills', '3', 'communication', 'Ketika menyampaikan kritik kepada teman, saya...', 'multiple_choice', 'mudah', NULL, '[{\"id\": 27001, \"teks\": \"Menyampaikan secara jelas tetapi tetap mempertimbangkan perasaannya.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 27002, \"teks\": \"Menyampaikan fakta masalah dan memberikan saran.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 27003, \"teks\": \"Memilih kata-kata yang sangat halus agar tidak menyinggung.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 27004, \"teks\": \"Cenderung menghindari memberikan kritik secara langsung.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[27001]', '15', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:28:25'),
('28', 'Situational Judgment Test (SJT)', '1', 'interpersonal', 'Saat bekerja dalam kelompok, kamu lebih menikmati...', 'multiple_choice', 'mudah', NULL, '[{\"id\": 28001, \"teks\": \"Berdiskusi dan bertukar ide dengan anggota lain.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 28002, \"teks\": \"Bekerja bersama tetapi tetap memiliki bagian sendiri.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 28003, \"teks\": \"Mengerjakan bagian tertentu secara mandiri.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 28004, \"teks\": \"Bekerja sendiri tanpa banyak interaksi.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[28001]', '16', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:28:25'),
('29', 'Emotional Intelligence', '2', 'emotional', 'Saat menghadapi masalah yang belum pernah kamu temui, kamu cenderung...', 'multiple_choice', 'sedang', NULL, '[{\"id\": 29001, \"teks\": \"Mencari kemungkinan baru dan beberapa alternatif solusi.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 29002, \"teks\": \"Mencari pengalaman atau contoh yang pernah digunakan.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 29003, \"teks\": \"Mencoba solusi yang menurut saya paling sederhana.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 29004, \"teks\": \"Menunggu arahan dari orang lain.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[29001]', '17', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:27:08'),
