('114', 'Situational Judgment Test (SJT)', '2', 'communication', 'Dosen memberi bacaan tambahan yang panjang dan rumit. Kamu...', 'dropdown', 'sedang', NULL, '[{\"id\": 114001, \"teks\": \"Membaca sambil membuat catatan konsep pentingnya.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 114002, \"teks\": \"Membaca satu kali lalu menandai bagian yang belum dipahami.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 114003, \"teks\": \"Membaca hanya bagian yang disebutkan di kelas.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 114004, \"teks\": \"Tidak membaca dan menunggu penjelasan dosen.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[114001]', '102', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
