('116', 'Situational Judgment Test (SJT)', '2', 'emotional', 'Ada dua opsi solusi dengan kelebihan dan kekurangan yang hampir sama. Kamu...', 'dropdown', 'sulit', NULL, '[{\"id\": 116001, \"teks\": \"Membandingkan konsekuensi masing-masing sebelum menentukan pilihan.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 116002, \"teks\": \"Memilih yang paling sesuai dengan kebutuhan utama saat itu.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 116003, \"teks\": \"Memilih opsi yang paling banyak disukai orang lain.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 116004, \"teks\": \"Memilih berdasarkan perasaan tanpa pertimbangan lanjutan.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[116001]', '104', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
