('120', 'Situational Judgment Test (SJT)', '3', 'emotional', 'Kamu menerima masukan yang terasa menyinggung dari dosen. Kamu...', 'dropdown', 'sedang', NULL, '[{\"id\": 120001, \"teks\": \"Mendengarkan sampai selesai lalu menilai bagian yang bisa diperbaiki.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 120002, \"teks\": \"Menanggapi setelah tenang dan menanyakan maksudnya lebih jelas.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 120003, \"teks\": \"Menerima tanpa membahasnya lagi.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 120004, \"teks\": \"Membalas dengan nada membela diri.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[120001]', '108', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
