('125', 'Situational Judgment Test (SJT)', '4', 'communication', 'Jadwal kegiatan kampusmu berubah secara tiba-tiba. Kamu...', 'dropdown', 'mudah', NULL, '[{\"id\": 125001, \"teks\": \"Menyesuaikan rencana dengan cepat dan menentukan prioritas baru.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 125002, \"teks\": \"Membuat ulang jadwal mingguan setelah kepastian perubahan terbit.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 125003, \"teks\": \"Tetap mengikuti rencana awal sebisa mungkin.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 125004, \"teks\": \"Merasa terganggu lalu menunda semua rencana.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[125001]', '113', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
('126', 'Situational Judgment Test (SJT)', '4', 'emotional', 'Saat mengerjakan tugas panjang, kamu cenderung...', 'dropdown', 'sedang', NULL, '[{\"id\": 126001, \"teks\": \"Membagi pekerjaan menjadi bagian kecil dengan tenggat sendiri.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 126002, \"teks\": \"Mengerjakan dalam satu kali duduk bila memungkinkan.\", \"bobot\": 3, \"urutan\": 2, \"indikator\": \"netral\"}, {\"id\": 126003, \"teks\": \"Mengerjakan bila mood sedang bagus.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 126004, \"teks\": \"Menunda sampai tenggat benar-benar dekat.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[126001]', '114', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
