('129', 'Emotional Intelligence', '1', 'communication', 'Saat ada kesempatan berkenalan dengan orang baru dalam kegiatan, kamu...', 'multiple_choice', 'mudah', NULL, '[{\"id\": 129001, \"teks\": \"Segera memanfaatkan kesempatan itu dan memulai percakapan.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 129002, \"teks\": \"Mencoba bila ada teman yang memperkenalkan.\", \"bobot\": 3, \"urutan\": 2, \"indikator\": \"netral\"}, {\"id\": 129003, \"teks\": \"Menunggu orang lain yang menyapa lebih dulu.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 129004, \"teks\": \"Menghindari karena merasa canggung.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[129001]', '117', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
('130', 'Emotional Intelligence', '2', 'emotional', 'Ketika menghadapi situasi yang membuatmu marah, kamu...', 'multiple_choice', 'sedang', NULL, '[{\"id\": 130001, \"teks\": \"Menahan reaksi lalu menyampaikan perasaan setelah dirimu tenang.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 130002, \"teks\": \"Menyampaikan perasaan dengan nada yang lebih rendah.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 130003, \"teks\": \"Meluapkan perasaan saat itu juga.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 130004, \"teks\": \"Menumpuk amarah sampai akhirnya meledak sendiri.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[130001]', '118', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
('131', 'Emotional Intelligence', '2', 'interpersonal', 'Saat mencoba memahami perasaan orang lain, kamu lebih mengandalkan...', 'multiple_choice', 'sulit', NULL, '[{\"id\": 131001, \"teks\": \"Nada bicara dan hal-hal yang tidak diucapkan langsung.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 131002, \"teks\": \"Perpaduan antara kata-kata dan sikap orang tersebut.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 131003, \"teks\": \"Ucapan yang benar-benar diucapkan saja.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 131004, \"teks\": \"Perkiraanmu sendiri tanpa memperhatikan orangnya.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[131001]', '119', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
('132', 'Emotional Intelligence', '3', 'emotional', 'Ketika menilai keputusan kelompok, kamu pertimbangkan...', 'multiple_choice', 'sedang', NULL, '[{\"id\": 132001, \"teks\": \"Dampak keputusan itu pada perasaan dan kondisi anggota kelompok.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 132002, \"teks\": \"Kebutuhan anggota sekaligus data yang tersedia.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 132003, \"teks\": \"Data dan angka saja.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 132004, \"teks\": \"Keputusan yang paling cepat diambil.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[132001]', '120', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
('133', 'Emotional Intelligence', '3', 'communication', 'Saat harus menolak permintaan teman, kamu...', 'multiple_choice', 'sedang', NULL, '[{\"id\": 133001, \"teks\": \"Menjelaskan alasannya sambil tetap menjaga perasaannya.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 133002, \"teks\": \"Menyampaikan penolakan dengan singkat namun sopan.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 133003, \"teks\": \"Menolak tanpa penjelasan agar cepat selesai.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 133004, \"teks\": \"Menghindari sampai teman itu sendiri yang mundur.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[133001]', '121', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
('134', 'Emotional Intelligence', '3', 'interpersonal', 'Dalam bekerja sama, kamu lebih menghargai...', 'multiple_choice', 'mudah', NULL, '[{\"id\": 134001, \"teks\": \"Usaha anggota kelompok untuk saling mendukung satu sama lain.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 134002, \"teks\": \"Hasil akhir yang sesuai target bersama.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 134003, \"teks\": \"Kepatuhan pada aturan yang sudah dibuat.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 134004, \"teks\": \"Cepat atau tidaknya tugas selesai.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[134001]', '122', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
('135', 'Emotional Intelligence', '4', 'emotional', 'Kamu menyusun rencana belajar untuk ujian akhir. Kamu...', 'multiple_choice', 'sedang', NULL, '[{\"id\": 135001, \"teks\": \"Membuat jadwal harian lalu mengikutinya bertahap.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 135002, \"teks\": \"Menetapkan target mingguan lalu menyesuaikan diri.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 135003, \"teks\": \"Belajar mengikuti situasi tanpa jadwal tetap.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 135004, \"teks\": \"Mengandalkan keadaan menjelang hari ujian.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[135001]', '123', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
('136', 'Emotional Intelligence', '3', 'emotional', 'Saat teman menceritakan masalah beratnya padamu, kamu...', 'multiple_choice', 'sulit', NULL, '[{\"id\": 136001, \"teks\": \"Mendengarkan penuh lalu membantu dia melihat pilihan penyelesaiannya.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 136002, \"teks\": \"Memberi dukungan tanpa menghakimi pilihannya.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 136003, \"teks\": \"Langsung menyarankan solusi terbaik menurutmu.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 136004, \"teks\": \"Menilai kesalahannya lebih dulu.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[136001]', '124', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
('137', 'Emotional Intelligence', '4', 'communication', 'Tugasmu menumpuk dan kamu baru mulai mengerjakannya. Kamu...', 'multiple_choice', 'sedang', NULL, '[{\"id\": 137001, \"teks\": \"Membuat urutan pengerjaan berdasarkan urgensi lalu menyelesaikannya satu per satu.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 137002, \"teks\": \"Mengerjakan bagian yang paling penting lebih dulu.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 137003, \"teks\": \"Mengerjakan semuanya sekaligus tanpa urutan.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 137004, \"teks\": \"Menunda karena merasa kewalahan.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[137001]', '125', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
('138', 'Emotional Intelligence', '1', 'interpersonal', 'Saat tidak ada kegiatan sama sekali, kamu biasanya...', 'dropdown', 'mudah', NULL, '[{\"id\": 138001, \"teks\": \"Mengajak teman atau mencari tempat yang ramai.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 138002, \"teks\": \"Menjalani kegiatan sendiri tetapi sesekali mencari orang.\", \"bobot\": 3, \"urutan\": 2, \"indikator\": \"netral\"}, {\"id\": 138003, \"teks\": \"Menghabiskan waktu sendirian seharian.\", \"bobot\": 2, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 138004, \"teks\": \"Menolak ajakan walaupun ada yang mengundang.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[138001]', '126', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
