('140', 'Emotional Intelligence', '2', 'communication', 'Saat menerima masukan dari orang lain, kamu...', 'dropdown', 'sedang', NULL, '[{\"id\": 140001, \"teks\": \"Membandingkannya dengan pengalaman lain lalu menarik pola umumnya.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 140002, \"teks\": \"Mencatat poin pentingnya untuk dipertimbangkan.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 140003, \"teks\": \"Menyimpannya apa adanya tanpa ditindaklanjuti.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 140004, \"teks\": \"Mengabaikan bila tidak sesuai kebiasaanmu.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[140001]', '128', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
