('142', 'Emotional Intelligence', '3', 'interpersonal', 'Saat menyelesaikan perbedaan dengan teman, kamu...', 'dropdown', 'sedang', NULL, '[{\"id\": 142001, \"teks\": \"Mengutamakan hubungan baik sambil mencari kata sepakat.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 142002, \"teks\": \"Menimbang kebutuhan kedua pihak secara sejajar.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 142003, \"teks\": \"Berpegang pada aturan yang sudah disepakati saja.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 142004, \"teks\": \"Menyelesaikan cepat tanpa membahas perasaan masing-masing.\", \"bobot\": 1, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[142001]', '130', 'aktif', '2026-10-09 18:49:15', '2026-10-09 18:49:15'),
